  public init(
    _ header: SyntaxNodeString,
    @MemberBlockItemListBuilder membersBuilder: () throws -> MemberBlockItemListSyntax
  ) throws {
    // If the type provides a custom `SyntaxParseable` implementation, use that. Otherwise construct it as a
